g2=[[4]*27 for _ in range(27)]
for r in range(27):g2[r][13]=1
for c in range(27):g2[13][c]=1
# original TL pattern
for r,c,v in [(3,6,5),(4,5,6),(4,6,5)]:g2[r][c]=v
for r in [5,6]:
 for c,v in [(4,3),(5,2),(6,2),(7,1),(8,1)]:g2[r][c]=v
# TR core & reflected attachments
for r in [5,6]:
 for c in [20,21]:g2[r][c]=2
for r,c,v in [(4,21,6),(3,20,5),(4,20,5)]:g2[r][c]=v
for r in [5,6]:g2[r][22]=3
for r in [5,6]:
 for c in [18,19]:g2[r][c]=1
# BL coarse pattern hypothesis
for r,c,v in [(20,3,2),(20,2,3),(20,4,1),(21,3,6),(21,4,5)]:g2[r][c]=v
# BR scaled 1.5 + 180 pattern (each template cell rectangle projected around core center)
# source cells in TL pattern are all colored pixels; paint scaled transform around core center=(5.5,5.5)
source=[]
for r,c,v in [(3,6,5),(4,5,6),(4,6,5)]:source.append((r,c,v))
for r in [5,6]:
 for c,v in [(4,3),(5,2),(6,2),(7,1),(8,1)]:source.append((r,c,v))
s=1.5; cr0=5.5;cc0=5.5; ctr=20.5;ctc=19.5
for r,c,v in source:
    # reverse coordinates and scale cell footprint around core center
    rlo=ctr - ((r+1)-cr0)*s; rhi=ctr - (r-cr0)*s
    clo=ctc - ((c+1)-cc0)*s; chi=ctc - (c-cc0)*s
    for rr in range(27):
      for cc in range(27):
        if (rr+0.5>=rlo-1e-9 and rr+0.5<rhi-1e-9 and cc+0.5>=clo-1e-9 and cc+0.5<chi-1e-9):
            g2[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in g2))

# test scaled 1.5 transformed template BR anchored at output core top-left (18,20)
g3=[row[:] for row in g2]
# erase previous BR outputs/seed region c16+ r14+ within BR quadrant; retain separators only
for r in range(14,27):
 for c in range(14,27):
  if (r,c)!=(13,13): g3[r][c]=4
# draw rotated/scaled template; core reference box rows5:7, cols5:7
s=1.5; ar,ac=18,20
for r,c,v in source:
  # 180 rotation, scale each unit cell around core rectangle; core maps to 3x3
  rlo=ar+(7-(r+1))*s; rhi=ar+(7-r)*s
  clo=ac+(7-(c+1))*s; chi=ac+(7-c)*s
  for rr in range(14,27):
   for cc in range(14,27):
    if rr+0.5>=rlo-1e-8 and rr+0.5<rhi-1e-8 and cc+0.5>=clo-1e-8 and cc+0.5<chi-1e-8:
     g3[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in g3[17:25]))

# Candidate 3: copy TL motif around each 2 core; scale = target core size / 2. TL left intact.
g4=[[4]*27 for _ in range(27)]
for r in range(27):g4[r][13]=1
for c in range(27):g4[13][c]=1
# template (test TL) cells
src=[]
for r,c,v in [(3,6,5),(4,5,6),(4,6,5)]:src.append((r,c,v))
for r in [5,6]:
 for c,v in [(4,3),(5,2),(6,2),(7,1),(8,1)]:src.append((r,c,v))
# Original test template
for r,c,v in src:g4[r][c]=v
# core locations/dimensions: TR2, BL4, BR2
# Transform template around source core [5:7,5:7], scale based side/2; each source cell expands s x s.
def paste(g, top, left, s, flip_v=False, flip_h=False):
  # local source pixel cell geometry relative to core square [5,7] each axis; transform reflection around center6.
  for r,c,v in src:
    # transform cell interval around reference core center; rotate/reflections then scale and anchor core top-left
    # coordinates in target relative to top-left of scaled core box
    if flip_v:
      ylo=(6-(r+1))*s+s  # wait desired core rows r5/r6 map ranges [s,2s],[0,s] => formula (7-(r+1))*s
      yhi=(7-r)*s
    else:
      ylo=(r-5)*s; yhi=(r-4)*s
    if flip_h:
      xlo=(7-(c+1))*s; xhi=(7-c)*s
    else:
      xlo=(c-5)*s; xhi=(c-4)*s
    # Correct vertical reflect interval formula: source core [5,7] -> target [0,2s]
    if flip_v:
      ylo=(7-(r+1))*s; yhi=(7-r)*s
    for rr in range(27):
      for cc in range(27):
        if (rr+0.5 >= top+ylo-1e-9 and rr+0.5 < top+yhi-1e-9 and cc+0.5 >= left+xlo-1e-9 and cc+0.5 < left+xhi-1e-9):
          g[rr][cc]=v
# first preserve cores
for r in [5,6]:
 for c in [20,21]:g4[r][c]=2
for r in range(19,23):
 for c in range(4,8):g4[r][c]=2
for r in [20,21]:
 for c in [19,20]:g4[r][c]=2
# paste pattern TR s1 horizontal reflect
paste(g4,5,20,1,flip_h=True)
# paste BL s2 vertical reflect; preserve core after overlay priority
paste(g4,19,4,2,flip_v=True)
for r in range(19,23):
 for c in range(4,8):g4[r][c]=2
# paste BR s1 both reflect then restore core
paste(g4,20,19,1,flip_v=True,flip_h=True)
for r in [20,21]:
 for c in [19,20]:g4[r][c]=2
print('\n'.join(' '.join(map(str,row)) for row in g4))
